import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.02.28
 */
public abstract class Plant extends Organism
{
    // Shared random source for plant lifecycle decisions.
    private static final Random rand = Randomizer.getRandom();

    /**
     * Create a new plant at location in field.
     * @param randomAge If true, the plant will have a random age assigned to it.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location);
        setAge(0);
        setWaterLevel(rand.nextInt(getStartingWaterLevelUpperBound()));
        if(randomAge) {
            setAge(rand.nextInt(getMaxAge()));
        }
    }

    /**
     * Make this plant act - that is: make it do whatever it needs to do.
     * @param newPlants A list to receive newly grown plants.
     */
    @Override
    public void act(List<Actor> newPlants)
    {
        super.act(newPlants);
        if (isAlive()) {
            giveBirth(newPlants);
            findWater();
        }
    }

    /**
     * Increase the age and kill the plant when it exceeds its lifespan.
     */
    @Override
    public void incrementAge()
    {
        super.incrementAge();
        if (getAge() > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Look for water adjacent to the plant's current location.
     * @return Where water was found, or null if it wasn't.
     */
    protected Location findWater()
    {
        return getWaterLevel() <= getWaterSearchThreshold() ? super.findWater() : null;
    }

    /**
     * Check whether or not this plant is to give birth at this step.
     * New growths will be made into free adjacent locations.
     * @param newPlants A list to return newly grown plants.
     */
    protected void giveBirth(List<Actor> newPlants)
    {
        int births = breed();
        if (births <= 0) {
            return;
        }

        List<Location> free = getBirthLocations();
        if (free == null) {
            return;
        }

        Field field = getField();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Organism young = createOffspring(field, loc);
            initializeOffspring(young);
            newPlants.add(young);
        }
    }

    /**
     * Find free adjacent locations for births if this plant can breed.
     */
    protected List<Location> getBirthLocations()
    {
        if (canBreed()) {
            return getField().getFreeAdjacentLocations(getLocation());
        }
        return null;
    }

    /**
     * Determine whether this plant can currently breed.
     */
    private boolean canBreed()
    {
        return getWaterLevel() >= getBreedingWaterThreshold();
    }

    /**
     * Generate the number of offspring produced by this plant.
     */
    private int breed()
    {
        if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            return rand.nextInt(getMaxLitterSize()) + 1;
        }
        return 0;
    }

    /**
     * @return The age at which this plant can die of old age.
     */
    protected abstract int getMaxAge();

    /**
     * @return The probability that this plant reproduces when conditions are met.
     */
    protected abstract double getBreedingProbability();

    /**
     * @return The maximum number of offspring this plant can produce at once.
     */
    protected abstract int getMaxLitterSize();

    /**
     * @return The minimum water level required to reproduce.
     */
    protected abstract int getBreedingWaterThreshold();

    /**
     * @return The upper bound used for initial water level generation.
     */
    protected abstract int getStartingWaterLevelUpperBound();

    /**
     * @return The water level at which the plant starts seeking water.
     */
    protected abstract int getWaterSearchThreshold();

    /**
     * Create a new offspring of the current plant species.
     * @param field The field the offspring should occupy.
     * @param location The offspring's location.
     * @return A new instance of the same plant species.
     */
    protected abstract Organism createOffspring(Field field, Location location);

    /**
     * Plants do not currently copy additional state to offspring.
     * @param offspring The offspring to initialize.
     */
    @Override
    protected void initializeOffspring(Organism offspring)
    {
        // Default plant offspring state is already complete.
    }
}

import java.util.Random;
import java.util.List;
import java.util.Iterator;
import java.util.ArrayList;

/**
 * A class to represent all living creatures in the simulation
 * Shared characteristics between organisms include whether they are alive,
 * their location on the field and their age
 *
 * @version 2022.02.27
 */
public abstract class Organism implements Actor
{
    // Whether the organism is alive or not
    private boolean alive;
    // The organism's field
    private Field field;
    // The organism's position in the field
    private Location location;
    // The water level of the organism
    private int waterLevel;
    // Whether the organism is infected with a disease or not.
    private boolean infected;
    // The organism's age
    private int age;

    /** 
     * Constructor for organisms - places new organism in location
     * 
     * @param randomAge If true, the organism will have random age
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Organism(boolean randomAge, Field field, Location location) 
    {
        alive = true;
        this.field = field;
        setLocation(location);
        age = 0;
    }

     /**
     * Make this organism act - that is: make it do
     * whatever it wants/needs to do.
     * All organisms will age and lose water with each step that they act
     *
     * @param newOrganisms A list to receive newly born organisms
     */
    public void act(List<Actor> newOrganisms)
    {
        incrementAge();
        decreaseWaterLevel();
    }

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

     /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    public void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Increase the age.
     */
    public void incrementAge()
    {
        age = age + 1;
    }

    /**
     * Apply shared parent state to a newly created offspring.
     * Subclasses can override to copy domain-specific state.
     * @param offspring The newly created offspring.
     */
    protected void initializeOffspring(Organism offspring)
    {
        // Default is intentionally empty.
    }

    /**
     * @return The value that eating this organism gives predator
     */
    abstract public int getFoodValue();

    /**
     * Look for water adjacent to the organism's current location
     * @return Where water was found, or null if it wasn't 
     */
    protected Location findWater() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()){
            Location where = it.next();
            Object waterSource = field.getObjectAt(where);
            if(waterSource instanceof Lake) {
                Lake lake = (Lake) waterSource;
                if(lake.getVolume() <= 0){
                    lake.setDead();
                    return null;
                }
                int waterDrawn = Math.min(lake.getWaterValue(), lake.getVolume());
                setWaterLevel(getWaterLevel() + waterDrawn);
                lake.reduceVolume(waterDrawn);
                if (lake.getVolume() <= 0) {
                    lake.setDead();
                }
                return where;
            }
        }
        return null;
    }

    /** 
     * Lower's the organism's water level - may result in its death
     */
    public void decreaseWaterLevel(){
        int newWaterLevel = getWaterLevel() - 1;
        setWaterLevel(newWaterLevel);
        if(getWaterLevel() <=0) {
            setDead();
        }
    }

    /**
     * @param waterValue The level of water an organism has 
     */
    protected void setWaterLevel(int newWaterLevel)
    {
        waterLevel = newWaterLevel;
    }

    /**
     * @return The current level of water an organism has
     */
    protected int getWaterLevel()
    {
        return waterLevel;
    }

    /**
     * @param age The current age of the organism
     */
    protected void setAge(int age)
    {
        this.age = age;
    }

    /**
     * @return Current age of the organism
     */
    protected double getAge()
    { 
        return age;
    }

    /**
     * Infects the organism with a disease
     */
    protected void setInfected() {
        infected = true;
    }

    /** 
     * Infection does not last forever in water, removes disease
     */
    protected void notInfected() {
        infected = false;
    }

    /**
     * @return Whether the organism is infected with a disease
     */
    protected boolean isInfected(){
        return infected;
    }
}

import java.util.Iterator;
import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.01
 */
public abstract class Animal extends Organism
{
    // Shared random source for animal lifecycle decisions.
    private static final Random rand = Randomizer.getRandom();
    // The level of food an animal has consumed, increases when it eats
    private int foodLevel;
    // Indicates whether an animal can give birth or not
    private boolean female;
    // Indicates whether the animal is nocturnal or not
    private boolean nocturnal;
    // The animal's age
    private double age;
    // Indicates whether the animal is sleeping or not
    private boolean sleeping;

    /**
     * Create a new animal at location in field.
     * 
     * @param randomAge If true, the animal will have a random age
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location);
        nocturnal = false;
        female = rand.nextBoolean();
        setWaterLevel(rand.nextInt(10) + 5);
        sleeping = false;
        if(!randomAge) {
            setAge(0);
            foodLevel = rand.nextInt(10) + 8;
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     */
    public void act(List<Actor> newOrganisms) {
        // All animals eat; all organisms also increment age and water level
        super.act(newOrganisms);
        incrementHunger();
        if(isAlive() && !sleeping) {        
            // Move towards a source of food if found
            giveBirth(newOrganisms);  
            Location newLocation = null;
            if(getWaterLevel() < 3) {
                newLocation = findWater();
            }
            if (newLocation == null && getFoodLevel() < 8 && rand.nextDouble() <= getHuntProbability()) {
                newLocation = findFood(getPrey());
            }
            if (newLocation == null) {
                newLocation = findMate();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
        else if (sleeping) {
            // code for what to do when sleeping
            sleeping = false;
        }
    }

    /**
     * Move towards another animal of the same species to find a mate to breed with
     * 
     * @return The location of a potential mate if found, null if not
     */
    protected Location findMate() 
    {
        if (hasCompatibleMateAdjacent()) {
            return getField().freeAdjacentLocation(getLocation());
        }
        return null;
    }

    /**
     * Increase the age and kill the animal when it exceeds its lifespan.
     */
    @Override
    public void incrementAge()
    {
        super.incrementAge();
        if (getAge() > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Look for prey adjacent to the current location.
     * Only the first live prey is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(List<String> preyList)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object food = field.getObjectAt(where);
            if(food!= null) {
                if(preyList.contains(food.getClass().getName())) {
                    Organism prey = (Organism) food;
                    if(prey.isAlive()) { 
                        prey.setDead();
                        int increment = prey.getFoodValue() + this.getFoodLevel();
                        this.setFoodLevel(increment);
                        int newWaterLevel = getWaterLevel() + 5;
                        this.setWaterLevel(newWaterLevel);
                        return where;  
                    }
                }
            }
        }
        return null;
    }

    /**
     * Make the animal more hungry. This could result in the animal's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Check whether or not this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        int births = breed();
        if (births <= 0) {
            return;
        }

        List<Location> free = getBirthLocations();
        if (free == null) {
            return;
        }

        Field field = getField();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Organism young = createOffspring(field, loc);
            initializeOffspring(young);
            newAnimals.add(young);
        }
    }

    /**
     * Find free adjacent locations for births if a compatible mate is nearby.
     * @return The free locations available for offspring, or null if breeding is not possible.
     */
    protected List<Location> getBirthLocations()
    {
        if (hasCompatibleMateAdjacent()) {
            return getField().getFreeAdjacentLocations(getLocation());
        }
        return null;
    }

    /**
     * @param foodValue The level of food an animal has eaten
     */
    protected void setFoodLevel(int foodValue)
    {
        foodLevel = foodValue;
    }

    /** 
     * @return The level of food an animal has eaten
     */
    protected int getFoodLevel()
    {
        return foodLevel;
    }

    /** 
     * @return True if this animal is a female, capable of breeding
     */
    public boolean isFemale()
    {
        return female;
    }

    /** 
     * @return True if this animal is a female, capable of breeding
     */
    protected void setNocturnal()
    {
        nocturnal = true;
    }

    /** 
     * @return True if this animal is nocturnal, false if not
     */
    public boolean isNocturnal()
    {
        return nocturnal;
    }

    /**
     * Sets the sleeping boolean variable to the opposite state it currently has.
     */
    protected void setSleepStatus(){
        sleeping = ! sleeping;
    }

    /**
     * @return Returns list of prey for each animal
     */
    abstract public List<String> getPrey();

    /**
     * @return The probability that this animal successfully hunts when it is hungry.
     */
    protected double getHuntProbability()
    {
        return 1.0;
    }

    /**
     * @return The age at which this animal can breed.
     */
    protected abstract int getBreedingAge();

    /**
     * @return The maximum age this animal can reach.
     */
    protected abstract int getMaxAge();

    /**
     * @return The chance this animal successfully breeds when it can breed.
     */
    protected abstract double getBreedingProbability();

    /**
     * @return The maximum litter size for this animal.
     */
    protected abstract int getMaxLitterSize();

    /**
     * Create a new offspring of the current species.
     * @param field The field the offspring should occupy.
     * @param location The offspring's location.
     * @return A new instance of the same species.
     */
    protected abstract Organism createOffspring(Field field, Location location);

    /**
     * Determine whether this animal can currently breed.
     */
    private boolean canBreed()
    {
        return isFemale() && getAge() >= getBreedingAge();
    }

    /**
     * Generate the number of offspring produced by this animal.
     */
    private int breed()
    {
        if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            return rand.nextInt(getMaxLitterSize()) + 1;
        }
        return 0;
    }

    /**
     * Copy animal-specific state into a newly created offspring.
     * @param offspring The offspring to initialize.
     */
    @Override
    protected void initializeOffspring(Organism offspring)
    {
        if (this.isInfected()) {
            offspring.setInfected();
        }
    }

    /**
     * Determine whether there is a compatible mate adjacent to this animal.
     */
    private boolean hasCompatibleMateAdjacent()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal != null && animal.getClass().equals(this.getClass())) {
                Animal mate = (Animal) animal;
                if (isFemale() != mate.isFemale()) {
                    return true;
                }
            }
        }
        return false;
    }
}

