115	    protected Location findFood(List<String> preyList)
116	    {
117	        Field field = getField();
118	        List<Location> adjacent = field.adjacentLocations(getLocation());
119	        Iterator<Location> it = adjacent.iterator();
120	        while(it.hasNext()) {
121	            Location where = it.next();
122	            Object food = field.getObjectAt(where);
123	            if(food!= null) {
124	                if(preyList.contains(food.getClass().getName())) {
125	                    Organism prey = (Organism) food;
126	                    if(prey.isAlive()) { 
127	                        prey.setDead();
128	                        int increment = prey.getFoodValue() + this.getFoodLevel();
129	                        this.setFoodLevel(increment);
130	                        int newWaterLevel = getWaterLevel() + 5;
131	                        this.setWaterLevel(newWaterLevel);
132	                        return where;  
133	                    }
134	                }
135	            }
136	        }
